<?php
namespace Database\Seeders; use Illuminate\Database\Seeder; use App\Models\{Property,LoyaltyTier,Promotion,GuestTag};
class HotelCrmSeeder extends Seeder {public function run():void {foreach(Property::all() as $p){$tiers=[['Bronze',0,0,1],['Silver',500,5,1.1],['Gold',1500,10,1.25],['Platinum',5000,15,1.5]];foreach($tiers as [$name,$min,$discount,$mult])LoyaltyTier::updateOrCreate(['property_id'=>$p->id,'name'=>$name],['minimum_points'=>$min,'discount_percent'=>$discount,'points_multiplier'=>$mult,'benefits'=>match($name){'Silver'=>['Priority check-in'],'Gold'=>['Priority check-in','Late checkout subject to availability'],'Platinum'=>['Priority check-in','Late checkout subject to availability','Room upgrade subject to availability'],default=>['Member offers']},'is_active'=>true]);foreach([['VIP','#7c3aed'],['Returning Guest','#2563eb'],['Corporate Guest','#059669'],['Special Occasion','#db2777']] as [$name,$colour])GuestTag::updateOrCreate(['property_id'=>$p->id,'name'=>$name],['colour'=>$colour]);Promotion::firstOrCreate(['property_id'=>$p->id,'code'=>'WELCOME10'],['name'=>'Welcome Offer','type'=>'percentage','value'=>10,'minimum_spend'=>100000,'maximum_discount'=>100000,'starts_at'=>now()->startOfDay(),'ends_at'=>now()->addYear(),'usage_limit'=>null,'per_guest_limit'=>1,'applies_to'=>['rooms'],'is_active'=>true]);}}
}
